#[cfg(test)]
mod order_cancel_request_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_order_cancel_request_codec() {
        let original = OrderCancelRequest {
            appl_id: "a".repeat(3),
            submitting_pbuid: "a".repeat(6),
            security_id: "a".repeat(8),
            security_id_source: "a".repeat(4),
            owner_type: 1234,
            clearing_firm: "a".repeat(2),
            transact_time: -123456789,
            user_info: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            orig_cl_ord_id: "a".repeat(10),
            side: "a".to_string(),
            order_id: "a".repeat(16),
            order_qty: -123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(OrderCancelRequestRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        OrderCancelRequest::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = OrderCancelRequest::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

